<script setup lang="ts">
import { Barcode, Check, Printer, RotateCcw } from '@lucide/vue'
import type { EntityFieldMeta } from '~/composables/useEntityFields'
import { DEFAULT_LABEL_CONFIG, LABEL_SIZES, type LabelConfig, code128Svg } from '~/utils/labelTemplates'

const props = defineProps<{ modelValue: LabelConfig; fields: EntityFieldMeta[]; moduleName: string }>()
const emit = defineEmits<{ 'update:modelValue': [value: LabelConfig] }>()
const config = computed({ get: () => props.modelValue, set: (value: LabelConfig) => emit('update:modelValue', value) })
const printableFields = computed(() => props.fields.filter(field => field.name !== 'id' && !['file', 'table', 'json'].includes(field.dataType)))
const textFields = computed(() => printableFields.value.filter(field => ['text', 'textarea', 'select', 'relation', 'incremental'].includes(field.dataType)))
const sampleValue = (name: string | null) => name ? (printableFields.value.find(field => field.name === name)?.label ?? name) : ''
const barcodePreview = computed(() => code128Svg('PROD-000123', 30))
const { data: branding } = useFetch<{ hasLogo: boolean }>('/api/tenant/branding', { key: 'label-editor-branding' })
const logoUrl = '/api/tenant/logo'
function update(patch: Partial<LabelConfig>) { config.value = { ...config.value, ...patch } }
function onSizeChange(size: LabelConfig['size']) { const preset = LABEL_SIZES[size]; update({ size, ...(size === 'custom' ? {} : { widthMm: preset.widthMm, heightMm: preset.heightMm }) }) }
function reset() { emit('update:modelValue', { ...DEFAULT_LABEL_CONFIG }) }
</script>

<template>
  <div class="label-editor-grid">
    <section class="flex min-w-0 flex-col rounded-lg border border-brand-border-light bg-brand-surface shadow-[0_1px_3px_0_#33475B14]">
      <div class="flex flex-wrap items-center justify-between gap-3 border-b border-brand-border-light p-5">
        <div class="flex flex-col gap-1"><div class="flex items-center gap-2"><h2 class="text-[15px] font-bold text-brand-text">Diseño de etiqueta</h2><ModuleTourHelpButton tab="labels" /></div><p class="text-sm text-brand-text-secondary">Usa los campos de {{ moduleName }} para crear una etiqueta reutilizable.</p></div>
        <div class="flex flex-wrap items-center gap-3"><div data-tour="edit-labels-toggle" class="label-toggles"><label class="toggle-row"><input :checked="config.enabled" type="checkbox" @change="update({ enabled: ($event.target as HTMLInputElement).checked })" /><span class="toggle-track"><span /></span><strong>{{ config.enabled ? 'Activo' : 'Desactivado' }}</strong></label><label v-if="branding?.hasLogo" class="toggle-row"><input :checked="config.showLogo" type="checkbox" @change="update({ showLogo: ($event.target as HTMLInputElement).checked })" /><span class="toggle-track"><span /></span><strong>Logo</strong></label></div><slot name="actions" /></div>
      </div>
      <div class="p-5">
      <div data-tour="edit-labels-fields" class="label-form-grid">
        <label>Formato<select :value="config.size" @change="onSizeChange(($event.target as HTMLSelectElement).value as LabelConfig['size'])"><option v-for="(preset, key) in LABEL_SIZES" :key="key" :value="key">{{ preset.label }}</option></select></label>
        <label v-if="config.size === 'custom'">Ancho (mm)<input :value="config.widthMm" type="number" min="20" max="300" @input="update({ widthMm: Number(($event.target as HTMLInputElement).value) || 20 })" /></label>
        <label v-if="config.size === 'custom'">Alto (mm)<input :value="config.heightMm" type="number" min="15" max="300" @input="update({ heightMm: Number(($event.target as HTMLInputElement).value) || 15 })" /></label>
        <label v-if="config.size !== 'custom'">Orientación<select :value="config.orientation" @change="update({ orientation: ($event.target as HTMLSelectElement).value as LabelConfig['orientation'] })"><option value="landscape">Horizontal</option><option value="portrait">Vertical</option></select></label>
        <label>Copias por registro<input :value="config.copies" type="number" min="1" max="100" @input="update({ copies: Math.min(100, Math.max(1, Number(($event.target as HTMLInputElement).value) || 1)) })" /></label>
        <label>Título principal<select :value="config.titleField ?? ''" @change="update({ titleField: ($event.target as HTMLSelectElement).value || null })"><option value="">Sin título</option><option v-for="field in textFields" :key="field.id" :value="field.name">{{ field.label }}</option></select></label>
        <label>Texto secundario<select :value="config.subtitleField ?? ''" @change="update({ subtitleField: ($event.target as HTMLSelectElement).value || null })"><option value="">Sin texto secundario</option><option v-for="field in textFields" :key="field.id" :value="field.name">{{ field.label }}</option></select></label>
        <label>Código de barras<select :value="config.barcodeField ?? ''" @change="update({ barcodeField: ($event.target as HTMLSelectElement).value || null })"><option value="">Sin código</option><option v-for="field in printableFields" :key="field.id" :value="field.name">{{ field.label }}</option></select></label>
        <label>Tipo de código<select :value="config.barcodeFormat" disabled><option value="code128">Code 128 (compatible)</option></select><small class="field-help">Ideal para SKU, folios y códigos internos.</small></label>
      </div>
      <div class="detail-fields-block"><div><strong>Datos adicionales</strong><span>Hasta 4 campos debajo del título</span></div><div class="detail-chip-list"><button v-for="field in printableFields" :key="field.id" type="button" :class="{ selected: config.detailFields.includes(field.name) }" @click="update({ detailFields: config.detailFields.includes(field.name) ? config.detailFields.filter(name => name !== field.name) : config.detailFields.length < 4 ? [...config.detailFields, field.name] : config.detailFields })"><Check v-if="config.detailFields.includes(field.name)" :size="13" />{{ field.label }}</button></div></div>
      <div class="label-actions"><button type="button" class="reset-button" @click="reset"><RotateCcw :size="14" /> Restaurar diseño</button><span><Barcode :size="14" /> Código generado al imprimir</span></div>
      </div>
    </section>
    <aside data-tour="edit-labels-preview" class="label-preview-card flex flex-col rounded-lg border border-brand-border-light bg-brand-surface shadow-[0_1px_3px_0_#33475B14]">
      <div class="preview-heading"><div><p class="eyebrow">Vista previa</p><h3>{{ LABEL_SIZES[config.size].label }}</h3></div><Printer :size="18" /></div>
      <div class="preview-stage"><div class="label-preview" :style="{ aspectRatio: `${config.widthMm} / ${config.heightMm}` }"><div class="preview-main" :class="{ 'with-logo': config.showLogo && branding?.hasLogo }"><img v-if="config.showLogo && branding?.hasLogo" :src="logoUrl" alt="" class="preview-logo" /><div class="preview-copy"><strong v-if="config.titleField" class="preview-title">{{ sampleValue(config.titleField) }}</strong><span v-if="config.subtitleField" class="preview-subtitle">{{ sampleValue(config.subtitleField) }}</span><div v-if="config.detailFields.length" class="preview-details"><span v-for="name in config.detailFields" :key="name">{{ sampleValue(name) }}</span></div></div></div><div v-if="config.barcodeField" class="preview-barcode" v-html="barcodePreview" /><small v-if="config.barcodeField">PROD-000123</small><div v-if="!config.titleField && !config.subtitleField && !config.barcodeField && !config.showLogo" class="preview-empty">Selecciona campos para comenzar</div></div></div>
      <p class="preview-note">La impresión utiliza medidas reales en milímetros y elimina márgenes del navegador.</p>
    </aside>
  </div>
</template>

<style scoped>
